  39 // Helper to create profile on first sign-in
  40 async function handleFirstSignIn(user: FirebaseUser) {
  41     // Check if a profile already exists by trying to fetch it.
  42     // We expect this to fail for a new user.
  43     const token = await user.getIdToken();
  44     try {
  45         const existingProfile = await fetchUserProfileApi(user.uid, token);
  46 
  47         if (!existingProfile) {
  48             // Profile doesn't exist, so create it.
  49             const profileData: Partial<UserProfile> = {
  50                 id: user.uid,
  51                 name: user.displayName || `User ${user.uid.slice(0,6)}`,
  52                 email: user.email || '',
  53             };
  54             await createOrUpdateUserProfileApi(user.uid, profileData, token);
  55         }
  56     } catch (error) {
  57         // Handle cases where the initial fetch fails for reasons other than 404
  58         console.error("Error during first sign-in profile check:", error);
  59     }
  60 }
